"""Prepare-heavy fuzz: mostly feasible proposals, plans verified independently."""
import sys, json, random, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
from verify_plan import verify_plan
from planner import deficient_cut

def new():
    for m in ['service','controller','planner','schema','fcflow','wire']:
        if m in sys.modules: del sys.modules[m]
    import service as sv
    return sv.handle

fails=[]
stats={}
def bad(m,c=None):
    fails.append(m); print('FAIL',m,json.dumps(c)[:300] if c is not None else '')

def gen_graph(rnd):
    n=rnd.choice([rnd.randint(3,9),rnd.randint(10,24),rnd.randint(25,48)])
    allp=[(u,v) for u in range(n) for v in range(u+1,n)]
    order=list(range(n)); rnd.shuffle(order)
    links=[[min(order[i],order[i+1]),max(order[i],order[i+1]),rnd.choice([1,2,3,5,10,10**3,10**6,10**12])] for i in range(n-1)]
    s={(min(a,b),max(a,b)) for a,b,_ in links}
    rest=[p for p in allp if p not in s]; rnd.shuffle(rest)
    extra=rnd.randint(0,min(len(rest),128-len(links)))
    links += [[u,v,rnd.choice([1,2,5,10,10**6,10**12])] for u,v in rest[:extra]]
    return n, links

def gen_prepare(rnd, n, links, T, feasible):
    nl=len(links)
    npart=rnd.randint(2,min(rnd.choice([3,8,32]),n))
    parts=rnd.sample(range(n),npart)
    base={v:rnd.choice([1,1,2,3,5,11,10**3,10**6]) for v in parts}
    if rnd.random()<0.3:
        base[rnd.choice(parts)]=0
    env={}
    for l in rnd.sample(range(nl),min(nl,rnd.randint(max(1,nl//4),nl))):
        env[l]=rnd.choice([1,2,3,5,10,10**3,10**6,10**12])
    per=rnd.choice([1,2,3,7,1000,10**6])
    caps=[per*env.get(l,0) for l in range(nl)]
    arcd={}
    for lid,(u,v,c) in enumerate(links):
        if caps[lid]>0:
            arcd[(u,v)]=arcd.get((u,v),0)+caps[lid]; arcd[(v,u)]=arcd.get((v,u),0)+caps[lid]
    P=sorted(parts)
    tot=sum(base.values())
    def ok(k):
        return deficient_cut(n,arcd,P,{v:base[v]*k for v in P},tot*k) is None
    if not ok(1):
        k=0
    else:
        lo,hi=1,2
        while ok(hi) and hi<2**60: hi*=2
        while lo+1<hi:
            mid=(lo+hi)//2
            if ok(mid): lo=mid
            else: hi=mid
        k=lo
    if feasible:
        if k==0: return None
        k=rnd.choice([k,k,k,max(1,k*3//4)])
    else:
        if k==0: k=1
        k=k*rnd.randint(2,5)+1
    rdem={v:base[v]*k for v in P}
    if sum(rdem.values())==0: return None
    s=rnd.randint(T,T+20); e=s+per*rnd.randint(1,5)
    if e>10**12: e=s+per
    if e<=s or e>10**12: return None
    return {'op':'prepare','id':rnd.choice(['j1','j2']),'owner':rnd.choice(['o','p']),
            'window':[s,e],'period':per,'participants':[[v,rdem[v]] for v in P],
            'envelope':[[l,r] for l,r in sorted(env.items())],'rev':0}

def run(seed):
    rnd=random.Random(seed)
    h=new()
    n,links=gen_graph(rnd)
    out=h({'op':'load','n':n,'links':links,'bookings':[]})
    if out!={'status':'ok','rev':0,'now':0}: bad('load',out); return
    T=0; R=0
    ids={}
    for i in range(12):
        want_feas = rnd.random()<0.75
        cmd=gen_prepare(rnd,n,links,T,want_feas)
        if cmd is None: continue
        cmd['rev']=R
        t0=time.time()
        out=h(cmd)
        dt=time.time()-t0
        stats['n'] = stats.get('n',0)+1
        stats[out['status']]=stats.get(out['status'],0)+1
        if dt>3: print('SLOW %.2f'%dt, 'n',n,'nl',len(links),'np',len(cmd['participants']))
        stats['maxdt']=max(stats.get('maxdt',0),dt)
        env={l:r for l,r in cmd['envelope']}
        caps=[cmd['period']*env.get(l,0) for l in range(len(links))]
        if out['status']=='prepared':
            parts={p[0]:p[1] for p in cmd['participants']}
            errs=[]
            ok=verify_plan(out['plan'],[(u,v) for u,v,_ in links],caps,cmd['period'],env,list(parts),parts,err=lambda m:errs.append(m))
            if not ok: bad('plan',(errs[:2],cmd))
            stats['trees']=max(stats.get('trees',0),len(out['plan']['trees']))
            stats['routes']=max(stats.get('routes',0),len(out['plan']['routes']))
            stats['rec']=max(stats.get('rec',0),len(out['plan']['recipes']))
            ids[cmd['id']]=cmd
        elif out['status']=='denied':
            if out['kind']=='capacity':
                s,e=cmd['window']; t=out['time']; l=out['link']
                if not(s<=t<e and out['used']>out['capacity'] and out['capacity']==caps[l] if True else False):
                    bad('cap witness',(out,caps))
            else:
                S=set(out['cut']); parts={p[0]:p[1] for p in cmd['participants']}
                inter=[v for v in out['cut'] if v in parts]
                tot=sum(caps[lid] for lid,(u,v,c) in enumerate(links) if (u in S)!=(v in S))
                dem=sum(parts[v] for v in inter)
                if not inter or len(inter)==len(parts) or not tot<dem:
                    bad('cut witness',(out,tot,dem))
            if want_feas: stats['unexpected_deny']=stats.get('unexpected_deny',0)+1
        else:
            bad('unexpected status',out)
        # commit prepared ids
        if out['status']=='prepared' and rnd.random()<0.6:
            c=h({'op':'commit','id':cmd['id'],'owner':cmd['owner'],'rev':R})
            if c['status']!='ok' or c['replay'] is not False: bad('commit',c)
            R+=1
            replay=h({'op':'commit','id':cmd['id'],'owner':cmd['owner'],'rev':0})
            if replay!={'status':'ok','id':cmd['id'],'rev':R,'replay':True}: bad('commit replay',replay)
            rep=h(dict(cmd, rev=R))
            if rep.get('status')!='replay' or rep.get('outcome')!='prepared' or rep.get('base_rev')!=R-1: bad('replay after commit',(rep,R))
        if rnd.random()<0.3:
            t=rnd.randint(T,T+50)
            a=h({'op':'advance','time':t})
            if a['status']!='ok': bad('advance',a)
            T=t; R+=1
t0=time.time()
N=int(sys.argv[1]) if len(sys.argv)>1 else 50
for seed in range(N):
    try: run(seed)
    except Exception as e:
        import traceback; traceback.print_exc(); bad('exc %s'%e); break
print('fails',len(fails),'stats',stats,'time %.1f'%(time.time()-t0))
